/* @lc app=leetcode id=3628 lang=kotlin */ class Solution { fun numOfSubsequences(s: String): Long = s.fold(Triple(0L, 0L, 0L)) { (l, lc, lct), c -> if (c == 'L') Triple(l + 1, lc, lct) else if (c == 'C') Triple(l, lc + l, lct) else if (c == 'T') Triple(l, lc, lct + lc) else Triple(l, lc, lct) }.let { (_, lc, lct) -> s.reversed().fold(Pair(0L, 0L)) { (t, ct), c -> if (c == 'T') (t + 1) to ct else if (c == 'C') t to (ct + t) else t to ct }.second.let { ctT -> s.runningFold(0L) { a, c -> a + if (c == 'L') 1 else 0 }.let { pl -> s.reversed().runningFold(0L) { a, c -> a + if (c == 'T') 1 else 0 }.reversed().let { st -> lct + maxOf(ctT, lc, (0..s.length).maxOf { pl[it] * st[it] }) } } } } }